export function clamp(value, low, high) {
  if (value < low) return low;
  if (value > high) return high;
  return value;
}

import { strict as assert } from "node:assert";
import { test } from "node:test";
import { clamp } from "./clamp.mjs";

test("leaves a value inside the range alone", () => {
  assert.equal(clamp(5, 0, 10), 5);
});

test("returns low when the value is below the range", () => {
  assert.equal(clamp(-1, 0, 10), 0);
});

test("returns high when the value is above the range", () => {
  assert.equal(clamp(11, 0, 10), 10);
});

test("returns low when the value equals the low bound", () => {
  assert.equal(clamp(0, 0, 10), 0);
});

test("returns high when the value equals the high bound", () => {
  assert.equal(clamp(10, 0, 10), 10);
});
